package ai.magpie.android;

import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.util.concurrent.atomic.AtomicReference;

/** Installed contracts: targets, context, and bounded primary navigation. No vendor accounts. */
public final class NativeNavigationAcceptance extends Instrumentation {
    private final AtomicReference<Activity> current=new AtomicReference<>();private String mode,addressA,addressB;private Activity home;
    @Override public void onCreate(Bundle b){super.onCreate(b);mode=b.getString("mode","flow");addressA=b.getString("addressA");addressB=b.getString("addressB");start();}
    @Override public void onStart(){try{
        Context c=getTargetContext();c.getSharedPreferences("host",0).edit().putBoolean("launched",true).putBoolean("askedNotifications",true).putBoolean("remote",false).commit();
        ((Application)c.getApplicationContext()).registerActivityLifecycleCallbacks(new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){current.set(a);Bundle trace=new Bundle();trace.putString("stream","RESUMED "+a.getClass().getSimpleName());sendStatus(1,trace);}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}});
        home=startActivitySync(new Intent(c,MainActivity.class).putExtra("catalogTab",mode.equals("cold")?1:0).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));
        if(mode.equals("cold")){require(((Integer)get(home,"catalogTab"))==1,"Cold start lost requested groups destination");waitFor(()->find(root(),"模型分组")!=null,"Group page title still ambiguous");pass();return;}
        if(mode.equals("target")){ui(()->{GatewayService.ready=true;try{Method m=MainActivity.class.getDeclaredMethod("selectCatalog",int.class,boolean.class);m.setAccessible(true);m.invoke(home,1,false);}catch(Exception e){throw new RuntimeException(e);}});
            AtomicReference<Intent> seen=new AtomicReference<>();ActivityMonitor monitor=new ActivityMonitor(){@Override public ActivityResult onStartActivity(Intent intent){seen.set(intent);return new ActivityResult(Activity.RESULT_CANCELED,null);}};addMonitor(monitor);
            ui(()->{try{((View)get(home,"catalogAction")).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->seen.get()!=null,"Group action didn't navigate");removeMonitor(monitor);
            require("groups".equals(seen.get().getStringExtra("view")),"Group action opens request routing instead of groups: "+seen.get().getStringExtra("view"));require(seen.get().getBooleanExtra("addGroup",false),"New group action does not open its editor");pass();return;
        }
        if(mode.equals("tools-screen")){
            click("工具");waitActivity("ToolsActivity");ui(()->((EditText)getField(current.get(),"search")).setText(""));capture("02-tools-directory");ui(()->((ScrollView)getField(current.get(),"scroll")).fullScroll(View.FOCUS_DOWN));capture("03-tools-bottom");pass();return;
        }
        if(mode.equals("parents")){
            click("工具");waitActivity("ToolsActivity");ui(()->{((EditText)getField(current.get(),"search")).setText("网关");GatewayService.ready=true;GatewayService.managementOrigin="http://127.0.0.1:1";});click("打开网关与访问密钥");waitActivity("ManagementActivity");require(find(root(),"返回工具")!=null,"Tools detail lost its source parent");lateErrorFinish();ui(()->current.get().onBackPressed());waitActivity("ToolsActivity");require("网关".contentEquals(((EditText)get(current.get(),"search")).getText()),"Detail return lost Tools query");ui(()->AppNavigation.primary(current.get(),"home"));waitActivity("MainActivity");ui(()->{((EditText)getField(current.get(),"search")).setText("parent-query");AppNavigation.detail(current.get(),"gateway");});waitActivity("ManagementActivity");require(find(root(),"返回模型")!=null,"Models detail incorrectly returns to Tools");lateErrorFinish();ui(()->current.get().onBackPressed());waitActivity("MainActivity");require("parent-query".contentEquals(((EditText)get(current.get(),"search")).getText()),"Detail return lost model query");pass();return;
        }
        if(mode.equals("setup")){
            ui(()->GatewayService.ready=false);home=startActivitySync(new Intent(c,ProviderSetupActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Activity setup=home;
            ui(()->{((EditText)getField(home,"address")).setText("https://draft.example/v1");((EditText)getField(current.get(),"key")).setText("unsaved-private-key");});click("改用订阅 / 高级添加 →");waitActivity("ManagementActivity");ui(()->current.get().onBackPressed());waitActivity("ProviderSetupActivity");require(current.get()==setup,"Advanced Back recreated/lost native draft");require("unsaved-private-key".contentEquals(((EditText)getField(current.get(),"key")).getText()),"Advanced Back lost draft key");
            click("改用订阅 / 高级添加 →");waitActivity("ManagementActivity");Activity advanced=current.get();click("工具");waitFor(()->get(advanced,"nativeLeaveDialog")!=null&&((AlertDialog)get(advanced,"nativeLeaveDialog")).isShowing(),"Root switch skipped native draft confirmation");ui(()->{try{((AlertDialog)get(advanced,"nativeLeaveDialog")).getButton(AlertDialog.BUTTON_NEGATIVE).performClick();}catch(Exception e){throw new RuntimeException(e);}});require(current.get()==advanced&&!setup.isFinishing(),"Cancel discarded the draft");click("工具");ui(()->{try{((AlertDialog)get(advanced,"nativeLeaveDialog")).getButton(AlertDialog.BUTTON_POSITIVE).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitActivity("ToolsActivity");waitFor(setup::isFinishing,"Approved primary switch stranded the native setup");pass();return;
        }
        if(mode.equals("workspace")){
            c.getSharedPreferences("host",0).edit().putBoolean("remote",true).putString("remoteAddress",addressA).putString("remoteKey","navigation-test-key-1234567890").commit();
            home=startActivitySync(new Intent(c,ToolsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->(Boolean)get(home,"busy"),"Slow workspace request never started");Thread.sleep(350);
            c.getSharedPreferences("host",0).edit().putString("remoteAddress",addressB).commit();ui(()->{try{for(String name:new String[]{"updateWorkspace","loadPages"}){Method m=home.getClass().getDeclaredMethod(name);m.setAccessible(true);m.invoke(home);}}catch(Exception e){throw new RuntimeException(e);}});
            waitFor(()->find(root(),"打开Workspace B page")!=null,"New workspace plugin pages blocked by stale request");Thread.sleep(2400);require(find(root(),"打开Workspace A page")==null,"Old workspace response replaced new pages");pass();return;
        }
        require(find(root(),"工具")!=null,"Permanent Tools page missing");
        capture("01-models");EditText query=(EditText)get(home,"search");ui(()->query.setText("retained catalog query"));click("工具");waitActivity("ToolsActivity");
        ui(()->((EditText)getField(current.get(),"search")).setText(""));capture("02-tools-directory");require(find(root(),"打开网关与访问密钥")!=null&&find(root(),"打开设置与备份")!=null,"Tools directory still hides important pages");
        EditText toolsSearch=(EditText)get(current.get(),"search");ui(()->toolsSearch.setText("备份"));require(find(root(),"打开设置与备份")!=null&&find(root(),"打开网关与访问密钥")==null,"Tools search does not filter the directory");ui(()->toolsSearch.setText(""));
        ui(()->current.get().onBackPressed());waitActivity("MainActivity");require(((EditText)get(current.get(),"search")).getText().toString().equals("retained catalog query"),"Returning from Tools cleared catalog context");
        click("用量");waitActivity("UsageActivity");EditText usageSearch=(EditText)get(current.get(),"modelSearch");ui(()->usageSearch.setText("persistent usage query"));click("工具");waitActivity("ToolsActivity");click("用量");waitActivity("UsageActivity");require(((EditText)get(current.get(),"modelSearch")).getText().toString().equals("persistent usage query"),"Primary switch lost usage filter");
        for(int i=0;i<3;i++){click("工具");waitActivity("ToolsActivity");click("用量");waitActivity("UsageActivity");}
        int count=((ActivityManager)c.getSystemService(Context.ACTIVITY_SERVICE)).getAppTasks().get(0).getTaskInfo().numActivities;require(count<=3,"Primary switching accumulates activities: "+count);pass();
    }catch(Throwable e){Bundle out=new Bundle();String diagnostic="";try{Activity a=current.get();diagnostic=" current="+a.getClass().getSimpleName()+" focus="+root().hasWindowFocus()+" origin="+GatewayService.managementOrigin;if(a instanceof ManagementActivity)diagnostic+=" loaded="+get(a,"pageLoaded")+" port="+(get(a,"exportPort")!=null)+" errorVisibility="+((View)get(a,"errorScroll")).getVisibility();android.graphics.Bitmap im=getUiAutomation().takeScreenshot();if(im!=null){java.io.File dir=new java.io.File(getTargetContext().getFilesDir(),"navigation-acceptance");dir.mkdirs();try(java.io.FileOutputStream f=new java.io.FileOutputStream(new java.io.File(dir,"failure-"+mode+".png"))){im.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}im.recycle();}}catch(Exception ignored){}out.putString("stream",android.util.Log.getStackTraceString(e)+diagnostic);finish(Activity.RESULT_CANCELED,out);}}
    private void lateErrorFinish()throws Exception{waitFor(()->current.get() instanceof ManagementActivity&&((View)get(current.get(),"errorScroll")).getVisibility()==View.VISIBLE,"Expected connection error page");ui(()->{android.webkit.WebView web=(android.webkit.WebView)getField(current.get(),"web");web.getWebViewClient().onPageFinished(web,GatewayService.managementOrigin+"/");});}
    private void capture(String name)throws Exception{waitFor(()->root().isAttachedToWindow()&&root().getWidth()>0&&root().hasWindowFocus(),"Screen is not laid out/focused");getUiAutomation().waitForIdle(500,10000);Thread.sleep(1600);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image==null)throw new AssertionError("Missing screenshot");java.io.File dir=new java.io.File(getTargetContext().getFilesDir(),"navigation-acceptance");dir.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(dir,name+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
    private void pass(){Bundle b=new Bundle();b.putString("stream","PASS navigation targets, native Tools, query retention and bounded primary stack");finish(Activity.RESULT_OK,b);}
    private View root(){return current.get().getWindow().getDecorView();}
    private static Object getField(Object o,String name){try{return get(o,name);}catch(Exception e){throw new RuntimeException(e);}}
    private static Object get(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
    private void ui(Runnable run){runOnMainSync(run);}
    private interface Check{boolean get()throws Exception;}
    private void waitFor(Check check,String why)throws Exception{long end=SystemClock.elapsedRealtime()+20000;while(SystemClock.elapsedRealtime()<end){AtomicReference<Boolean> ok=new AtomicReference<>(false);ui(()->{try{ok.set(check.get());}catch(Exception e){throw new RuntimeException(e);}});if(ok.get())return;Thread.sleep(100);}throw new AssertionError(why);}
    private void waitActivity(String name)throws Exception{waitFor(()->current.get()!=null&&current.get().getClass().getSimpleName().equals(name)&&root().isAttachedToWindow()&&root().getWidth()>0&&root().hasWindowFocus(),"Expected "+name);}
    private void click(String text)throws Exception{waitFor(()->find(root(),text)!=null,"Missing "+text);ui(()->{View v=find(root(),text);while(!v.isClickable()&&v.getParent() instanceof View)v=(View)v.getParent();v.performClick();});}
    private static View find(View v,String text){if(text.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||(v instanceof TextView&&text.contentEquals(((TextView)v).getText())))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View f=find(((ViewGroup)v).getChildAt(i),text);if(f!=null)return f;}return null;}
    private static void require(boolean ok,String why){if(!ok)throw new AssertionError(why);}
}
